import{_t as e,it as t,n,rt as r}from"./chunks/framework.GGfqtSwG.js";var i=JSON.parse(`{"title":"关于","description":"","frontmatter":{"title":"关于","pageClass":"about","masthead":true,"name":"关于这个示例","tag":"关于 · ABOUT","meta":"虚构内容 · 用来展示主题"},"headers":[],"relativePath":"about.md","filePath":"about.md"}`),a={name:`about.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p>这是一份<strong>虚构内容</strong>的博客，只为展示主题长什么样。这里的人、项目、数据都不存在。</p><h2 id="为什么会有这个站" tabindex="-1">为什么会有这个站 <a class="header-anchor" href="#为什么会有这个站" aria-label="Permalink to “为什么会有这个站”">​</a></h2><p>主题在自家站点里被用到极致：首页刊头、作品墙、Now 月度留档、杂志化的关于页。 但那样看不出「我只想搭个普通博客」会得到什么。</p><p>所以这里只保留最普通的三件事：<strong>文章列表、文章页、归档页</strong>。 没有作品墙，没有 Now，没有自定义组件——一个装了主题的 VitePress 博客本来的样子。</p><h2 id="页面里演示了什么" tabindex="-1">页面里演示了什么 <a class="header-anchor" href="#页面里演示了什么" aria-label="Permalink to “页面里演示了什么”">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>演示的东西</th></tr></thead><tbody><tr><td>首页</td><td><code>layout: home</code> 触发的刊头 + 最新文章列表</td></tr><tr><td>文章列表</td><td><code>.post-list</code> 的日期列与摘要</td></tr><tr><td>文章页</td><td>标题、层级、代码块、表格、提示块、列表标记</td></tr><tr><td>归档页</td><td><code>.archive-timeline</code> 的年份分组与行首日期</td></tr><tr><td>本页</td><td><code>pageClass: about</code> + <code>masthead</code> 页头与章节编号</td></tr></tbody></table><h2 id="内容怎么组织的" tabindex="-1">内容怎么组织的 <a class="header-anchor" href="#内容怎么组织的" aria-label="Permalink to “内容怎么组织的”">​</a></h2><ul><li>文章放 <code>posts/</code> 下，按主题分子目录；</li><li>每篇的 frontmatter 只写 <code>title</code> / <code>date</code> / <code>description</code>；</li><li>列表页 <code>posts/index.md</code> 与归档页 <code>archive.md</code> 用同一个数据源， 由 <code>posts/posts.data.ts</code> 在构建期扫出来，不用手工维护目录。</li></ul><h2 id="想自己试" tabindex="-1">想自己试 <a class="header-anchor" href="#想自己试" aria-label="Permalink to “想自己试”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># 在主题仓库根目录</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> example:dev</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">     # 就是你现在看的这个站</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">        # 主题作者自己的站点，样式用得最满</span></span></code></pre></div>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};